def merge(intervals: list[list[int]]) -> list[list[int]]:
    """Merge overlapping or touching closed intervals.

    The input is left unchanged, and the returned intervals are sorted by start.
    """
    ordered = sorted((list(interval) for interval in intervals), key=lambda interval: interval[0])
    merged: list[list[int]] = []
    for start, end in ordered:
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged
